import "server-only";
import { z } from "zod";
import { fetchJson } from "../http";
import type { NaturalEvent } from "@/lib/types";

/** All M2.5+ earthquakes of the past 7 days, regenerated by USGS every minute. */
const WEEK_FEED = "https://earthquake.usgs.gov/earthquakes/feed/v1.0/summary/2.5_week.geojson";

/**
 * Days 8–14 come from the FDSN event service. USGS asks clients to prefer the summary feeds for
 * frequent polling, so this older range is fetched rarely (see the collector in sources.ts).
 */
export function olderRangeUrl(now = Date.now()) {
  const day = 86_400_000;
  const params = new URLSearchParams({
    format: "geojson",
    starttime: new Date(now - 14 * day).toISOString().slice(0, 19),
    endtime: new Date(now - 7 * day).toISOString().slice(0, 19),
    minmagnitude: "2.5",
    orderby: "time",
  });
  return `https://earthquake.usgs.gov/fdsnws/event/1/query?${params}`;
}

const feature = z.object({
  id: z.string(),
  properties: z.object({
    mag: z.number().nullable(),
    magType: z.string().nullable().optional(),
    place: z.string().nullable(),
    time: z.number(),
    updated: z.number().nullable(),
    url: z.string(),
    status: z.string().nullable().optional(),
    tsunami: z.number().nullable().optional(),
    alert: z.string().nullable().optional(),
    title: z.string().nullable().optional(),
  }),
  geometry: z.object({
    type: z.literal("Point"),
    coordinates: z.tuple([z.number(), z.number()]).rest(z.number().nullable()),
  }),
});

const collection = z.object({ features: z.array(z.unknown()) });

export function normalizeUsgsFeature(raw: unknown): NaturalEvent | null {
  const parsed = feature.safeParse(raw);
  if (!parsed.success) return null;
  const { id, properties: p, geometry } = parsed.data;
  const [lon, lat, depth] = geometry.coordinates;
  const time = new Date(p.time).toISOString();
  const magnitude =
    p.mag === null ? null : { value: p.mag, unit: p.magType ? `M${p.magType}` : "M" };

  return {
    id: `usgs:${id}`,
    provider: "usgs",
    providerEventId: id,
    title: p.title?.trim() || `Earthquake${p.place ? `, ${p.place}` : ""}`,
    category: "earthquakes",
    lon,
    lat,
    approximate: false,
    track: [{ lon, lat, time, magnitude: p.mag }],
    startedAt: time,
    observedAt: time,
    providerUpdatedAt: p.updated ? new Date(p.updated).toISOString() : null,
    status: p.status ?? null,
    magnitude,
    description: p.place ?? null,
    links: [{ label: "USGS event page", url: p.url }],
    tsunami: p.tsunami === 1,
    alert: p.alert ?? null,
    depthKm: typeof depth === "number" ? depth : null,
  };
}

async function load(url: string) {
  const { features } = collection.parse(await fetchJson(url, { timeoutMs: 30_000 }));
  return features.map(normalizeUsgsFeature).filter((e): e is NaturalEvent => e !== null);
}

export const loadUsgsWeek = () => load(WEEK_FEED);
export const loadUsgsOlder = () => load(olderRangeUrl());
